#!/usr/bin/env python3
"""Run the held-out suite with the rule and skill generated by ctx7 setup."""
import argparse
from concurrent.futures import ThreadPoolExecutor, as_completed
from difflib import unified_diff
import json
import os
from pathlib import Path
import shutil
import tempfile
from types import SimpleNamespace

from run import run_turn


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--project", type=Path, required=True, help="Neutral fixture after ctx7 setup")
    parser.add_argument("--url", required=True, help="Benchmark MCP endpoint")
    parser.add_argument("--output", type=Path, required=True)
    parser.add_argument("--binary", default="claude")
    parser.add_argument("--model", default="claude-opus-5-5")
    parser.add_argument("--workers", type=int, default=14)
    parser.add_argument("--timeout", type=int, default=240)
    parser.add_argument("--case", type=int, action="append", help="Run specific held-out case numbers")
    args = parser.parse_args()
    args.agent = "claude"
    source = args.project.resolve(strict=True)
    for name in (".mcp.json", ".claude/rules/context7.md", ".claude/skills/context7-mcp/SKILL.md"):
        if not (source / name).is_file():
            parser.error(f"Missing installer output: {name}")
    cases = [
        case for case in json.loads(Path(__file__).with_name("trigger-eval-all.json").read_text())
        if case.get("set") == "heldout"
    ]
    selected = args.case or list(range(1, len(cases) + 1))
    if any(i < 1 or i > len(cases) for i in selected) or len(selected) != len(set(selected)):
        parser.error("Case numbers must be unique and within the held-out set.")
    env = os.environ.copy()
    key = env.pop("CONTEXT7_API_KEY", None)
    judge_key = env.pop("OPENROUTER_API_KEY", None)
    if not key:
        parser.error("Set CONTEXT7_API_KEY before running the benchmark.")
    for name in ("CLAUDECODE", "ENABLE_TOOL_SEARCH", "MCP_CONNECTION_NONBLOCKING"):
        env.pop(name, None)
    env["CLAUDE_CODE_DISABLE_AUTO_MEMORY"] = "1"
    os.umask(0o077)

    with tempfile.TemporaryDirectory(prefix="installed-mcp-eval-") as scratch:
        project = Path(scratch) / "project"
        shutil.copytree(source, project)
        config = project / ".mcp.json"
        data = json.loads(config.read_text())
        entry = data["mcpServers"]["context7"]
        entry["url"] = args.url
        entry["headers"] = {"Authorization": f"Bearer {key}"}
        config.write_text(json.dumps(data))
        # The single patch case gets its own checkout so other cases see the pristine fixture.
        edit_project = Path(scratch) / "patch-project"
        if 81 in selected:
            shutil.copytree(project, edit_project)

        def run_case(i):
            edit = i == 81
            cwd = edit_project if edit else project
            client = SimpleNamespace(agent="claude", binary=args.binary, model=args.model,
                                     timeout=args.timeout, project=cwd)
            calls, answer, _, error, tool_errors, _ = run_turn(
                client, env, cwd / ".mcp.json", cases[i - 1]["query"], max_turns=16,
                extra_tools=("Edit", "Write") if edit else (),
            )
            diff = None
            if edit:
                name = "README.md"
                diff = "".join(unified_diff(
                    (project / name).read_text().splitlines(keepends=True),
                    (edit_project / name).read_text().splitlines(keepends=True),
                    fromfile="before", tofile="after",
                ))
            for secret in filter(None, (key, judge_key)):
                answer = answer.replace(secret, "[redacted]")
                if diff:
                    diff = diff.replace(secret, "[redacted]")
            return {
                "i": i, "error": error, "calls": [name for name, _ in calls],
                "answer": answer, "diff": diff, "tool_errors": tool_errors,
            }

        failures = 0
        with args.output.open("x") as output, ThreadPoolExecutor(max_workers=args.workers) as pool:
            for job in as_completed([pool.submit(run_case, i) for i in selected]):
                row = job.result()
                output.write(json.dumps(row) + "\n")
                output.flush()
                failures += bool(row["error"])
        return int(bool(failures))


if __name__ == "__main__":
    raise SystemExit(main())
